flowchart TD
  P["Petición y su contexto: acción, recurso, claves como aws:SourceIp"] --> F["Una sentencia cuenta solo si acción, recurso, principal y condición coinciden"]
  F --> D{"¿Algún Deny aplicable en identidad, recurso o límite?"}
  D -- "Sí" --> X["Denegación explícita"]
  D -- "No" --> A{"¿Algún Allow aplicable en identidad o en recurso?"}
  A -- "No" --> I["Denegación implícita"]
  A -- "Sí" --> U{"¿Lo concede la política de recurso con el ARN del usuario como Principal?"}
  U -- "Sí, misma cuenta" --> OK["Permiso"]
  U -- "No" --> L{"¿Hay límite de permisos y no incluye la acción?"}
  L -- "Sí" --> I
  L -- "No" --> OK

const identidad = {
  Version: "2012-10-17",
  Statement: [
    {
      Sid: "LeerYEscribirFacturas",
      Effect: "Allow",
      Action: ["s3:GetObject", "s3:PutObject"],
      Resource: "arn:aws:s3:::amzn-s3-demo-bucket-facturas/*",
    },
  ],
};
const limite = {
  Version: "2012-10-17",
  Statement: [
    { Sid: "SoloLeer", Effect: "Allow", Action: "s3:GetObject", Resource: "arn:aws:s3:::amzn-s3-demo-bucket-facturas/*" },
  ],
};
const recurso = {
  Version: "2012-10-17",
  Statement: [
    {
      Sid: "SoloDesdeLaOficina",
      Effect: "Deny",
      Principal: "*",
      Action: "s3:*",
      Resource: ["arn:aws:s3:::amzn-s3-demo-bucket-facturas", "arn:aws:s3:::amzn-s3-demo-bucket-facturas/*"],
      Condition: { NotIpAddress: { "aws:SourceIp": "203.0.113.0/24" } },
    },
  ],
};
const decide = (action: string, ip: string) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::111122223333:user/contable", accountId: "111122223333" },
      action,
      resource: { arn: "arn:aws:s3:::amzn-s3-demo-bucket-facturas/2026/enero.pdf", accountId: "111122223333" },
      context: { "aws:SourceIp": ip },
    },
    identityPolicies: [identidad],
    permissionsBoundary: limite,
    resourcePolicy: recurso,
  }).decision;
console.log(decide("s3:GetObject", "203.0.113.20"));  // Allow
console.log(decide("s3:PutObject", "203.0.113.20"));  // ImplicitDeny: el límite no incluye PutObject
console.log(decide("s3:GetObject", "198.51.100.8"));  // ExplicitDeny: la condición del Deny se cumple
console.log(decide("s3:PutObject", "198.51.100.8"));  // ExplicitDeny: el Deny gana al resto

